  LinearLayout tools=a.column();FrameLayout.LayoutParams tp=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.RIGHT);tp.setMargins(0,a.dp(8),a.dp(8),0);addView(tools,tp);
  tools.setBackground(MobileUi.shape(a,MobileUi.surface(a),12));tools.addView(MobileUi.tool(a,"图层","图层",()->new AlertDialog.Builder(a).setTitle("底图类型").setSingleChoiceItems(new String[]{"普通","卫星"},selectedType==TencentMap.MAP_TYPE_NORMAL?0:1,(dialog,which)->{selectedType=which==0?TencentMap.MAP_TYPE_NORMAL:TencentMap.MAP_TYPE_SATELLITE;if(map!=null)map.setMapType(selectedType);dialog.dismiss();}).setNegativeButton("取消",null).show()));tools.addView(MobileUi.tool(a,"全览","全览",this::fit));
