 void showPhotos(List<PhotoStore.Photo> photos){List<PhotoStore.Photo> sorted=new ArrayList<>(photos);sorted.sort((x,y)->{long a=x instanceof GalleryRepository.Item?((GalleryRepository.Item)x).taken:0,b=y instanceof GalleryRepository.Item?((GalleryRepository.Item)y).taken:0;int c=Long.compare(b,a);return c!=0?c:x.uri.compareTo(y.uri);});Dialog sheet=new Dialog(a);LinearLayout panel=a.column();panel.setPadding(a.dp(16),a.dp(12),a.dp(16),a.dp(12));panel.setBackground(MobileUi.shape(a,MobileUi.surface(a),20));LinearLayout head=new LinearLayout(a);head.addView(a.text("此处照片 · "+sorted.size(),18),new LinearLayout.LayoutParams(0,-2,1));a.button(head,"关闭",sheet::dismiss);panel.addView(head);ListView list=new ListView(a);list.setAdapter(new BaseAdapter(){public int getCount(){return sorted.size();}public Object getItem(int n){return sorted.get(n);}public long getItemId(int n){return n;}public View getView(int n,View old,ViewGroup parent){PhotoStore.Photo p=sorted.get(n);LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);row.addView(image,new LinearLayout.LayoutParams(a.dp(72),a.dp(72)));a.thumbnail(p,image,200);TextView label=a.text(p.name+"\n"+(p.time==null?"":p.time),13);label.setPadding(a.dp(12),a.dp(8),0,a.dp(8));row.addView(label,new LinearLayout.LayoutParams(0,-2,1));row.setOnClickListener(v->{sheet.dismiss();a.detail(p);});return row;}});panel.addView(list,new LinearLayout.LayoutParams(-1,a.dp(330)));sheet.setContentView(panel);sheet.show();sheet.getWindow().setLayout(-1,-2);sheet.getWindow().setGravity(Gravity.BOTTOM);}
 static int newest(PhotoStore.Photo x,PhotoStore.Photo y){long xt=x instanceof GalleryRepository.Item?((GalleryRepository.Item)x).taken:0,yt=y instanceof GalleryRepository.Item?((GalleryRepository.Item)y).taken:0;int c=Long.compare(yt,xt);return c!=0?c:x.uri.compareTo(y.uri);}
 void loadCover(String groupKey,Marker marker,List<PhotoStore.Photo> photos,long token){PhotoStore.Photo latest=photos.get(0);String signature=latest instanceof GalleryRepository.Item?((GalleryRepository.Item)latest).signature:"";String key=groupKey+":"+latest.uri+":"+signature+":"+photos.size();if(key.equals(covers.get(groupKey)))return;BitmapDescriptor cached=coverCache.get(key);if(cached!=null){covers.put(groupKey,key);marker.setIcon(cached);return;}String pending=token+":"+key;if(pending.equals(pendingCovers.get(groupKey)))return;pendingCovers.put(groupKey,pending);long revision=a.app.gallery.revision;String uri=latest.uri;int count=photos.size();try{coverLoader.execute(()->{try{Bitmap photo=a.getContentResolver().loadThumbnail(android.net.Uri.parse(uri),new android.util.Size(160,160),null);Bitmap bitmap=Bitmap.createBitmap(156,172,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bitmap);Paint p=new Paint(3);p.setColor(Color.WHITE);c.drawRoundRect(3,3,153,153,18,18,p);Path clip=new Path();clip.addRoundRect(9,9,147,147,13,13,Path.Direction.CW);c.save();c.clipPath(clip);c.drawBitmap(photo,null,new Rect(9,9,147,147),p);c.restore();p.setColor(MobileUi.TEAL);Path tip=new Path();tip.moveTo(61,151);tip.lineTo(78,170);tip.lineTo(95,151);c.drawPath(tip,p);c.drawRoundRect(94,3,153,42,17,17,p);p.setColor(Color.WHITE);p.setTextSize(25);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextAlign(Paint.Align.CENTER);c.drawText(""+count,123,31,p);BitmapDescriptor icon=BitmapDescriptorFactory.fromBitmap(bitmap);a.runOnUiThread(()->{if(pending.equals(pendingCovers.get(groupKey)))pendingCovers.remove(groupKey);if(a.isDestroyed()||map==null||token!=drawToken||revision!=a.app.gallery.revision||markers.get(groupKey)!=marker)return;covers.put(groupKey,key);coverCache.put(key,icon);marker.setIcon(icon);});}catch(Exception ignored){a.runOnUiThread(()->{if(pending.equals(pendingCovers.get(groupKey)))pendingCovers.remove(groupKey);});}});}catch(java.util.concurrent.RejectedExecutionException ignored){pendingCovers.remove(groupKey);postDelayed(()->{if(map!=null){lastRender="";draw();}},500);}}
 BitmapDescriptor icon(int count){Bitmap b=Bitmap.createBitmap(92,100,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);Paint p=new Paint(3);p.setColor(Color.WHITE);c.drawRoundRect(2,2,90,88,12,12,p);p.setColor(0xffcfe5df);c.drawRoundRect(7,7,85,83,9,9,p);p.setColor(MobileUi.TEAL);Path mountain=new Path();mountain.moveTo(14,72);mountain.lineTo(35,38);mountain.lineTo(48,56);mountain.lineTo(62,44);mountain.lineTo(80,72);c.drawPath(mountain,p);c.drawCircle(27,25,7,p);Path tip=new Path();tip.moveTo(34,86);tip.lineTo(46,99);tip.lineTo(58,86);c.drawPath(tip,p);c.drawRoundRect(53,2,90,28,10,10,p);p.setColor(Color.WHITE);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(19);p.setTypeface(Typeface.DEFAULT_BOLD);c.drawText(""+count,71,22,p);return BitmapDescriptorFactory.fromBitmap(b);}

 void fit(){if(map==null||authFailed)return;List<PhotoStore.Photo> ps=a.app.gallery.located();if(ps.isEmpty()){message.setText(a.app.gallery.progress());return;}if(ps.size()==1){focus(ps.get(0));return;}LatLngBounds.Builder b=new LatLngBounds.Builder();for(PhotoStore.Photo p:ps){double[] q=Coordinates.gcj(p.lat,p.lon);b.include(new LatLng(q[0],q[1]));}initialFocused=true;LatLngBounds bounds=b.build();view.post(()->{if(map!=null)try{map.moveCamera(CameraUpdateFactory.newLatLngBounds(bounds,60));lastRender="";draw();}catch(Exception ignored){}});}
